sys_script.script:
(function executeRule(current, previous /* null when async */) {

    // =====================================================
    // NEXORA PLACEMENT BUSINESS RULE
    //
    // CONDITION:
    // Interview Status = Completed
    // AND
    // Interview Result = Pass
    //
    // Interview
    //    ↓
    // Application
    //    ↓
    // Student
    //
    // Student Placement Status = Placed
    // =====================================================


    // -----------------------------------------------------
    // 1. CHECK INTERVIEW STATUS
    // -----------------------------------------------------

    var interviewStatus =
        current.getValue('status');


    // -----------------------------------------------------
    // 2. CHECK INTERVIEW RESULT
    // -----------------------------------------------------

    var interviewResult =
        current.getValue('result');


    // -----------------------------------------------------
    // 3. ONLY COMPLETED + PASS
    // -----------------------------------------------------

    if (
        interviewStatus != 'completed' ||
        interviewResult != 'pass'
    ) {

        return;
    }


    // -----------------------------------------------------
    // 4. GET APPLICATION
    //
    // Interview field:
    // application
    // -----------------------------------------------------

    var applicationId =
        current.getValue('application');


    if (!applicationId) {

        gs.warn(
            'Nexora Placement: Interview ' +
            current.getUniqueValue() +
            ' has no Application reference.'
        );

        return;
    }


    // -----------------------------------------------------
    // 5. GET APPLICATION RECORD
    // -----------------------------------------------------

    var applicationGR =
        current
            .getElement('application')
            .getRefRecord();


    if (
        !applicationGR ||
        !applicationGR.isValidRecord()
    ) {

        gs.warn(
            'Nexora Placement: Application record not found for Interview ' +
            current.getUniqueValue()
        );

        return;
    }


    // -----------------------------------------------------
    // 6. GET STUDENT FROM APPLICATION
    //
    // Application field:
    // student
    // -----------------------------------------------------

    var studentId =
        applicationGR.getValue('student');


    if (!studentId) {

        gs.warn(
            'Nexora Placement: Application ' +
            applicationGR.getUniqueValue() +
            ' has no Student reference.'
        );

        return;
    }


    // -----------------------------------------------------
    // 7. GET STUDENT
    // -----------------------------------------------------

    var studentGR =
        new GlideRecord(
            'x_snc_college_pl_0_student'
        );


    if (
        !studentGR.get(studentId)
    ) {

        gs.warn(
            'Nexora Placement: Student record not found: ' +
            studentId
        );

        return;
    }


    // -----------------------------------------------------
    // 8. UPDATE PLACEMENT STATUS
    // -----------------------------------------------------

    studentGR.setValue(
        'placement_status',
        'placed'
    );


    // -----------------------------------------------------
    // 9. SAVE STUDENT
    // -----------------------------------------------------

    studentGR.update();


    // -----------------------------------------------------
    // 10. LOG
    // -----------------------------------------------------

    gs.info(
        'Nexora Placement: Student ' +
        studentGR.getDisplayValue() +
        ' marked as Placed after Completed + Pass interview.'
    );


})(current, previous);
